// Regra Rígida de Sentinela:
// Variação > 5% em 1h ou perda de suporte técnico de longo prazo
const precoAtual = parseFloat($input.first().json.lastPrice);
const variacao24h = parseFloat($input.first().json.priceChangePercent);

// Estimativa determinística de variação em 1 hora
const variacao1hEstimada = variacao24h / 6.0; 
const suporteCritico = 55000.0;
const quebrouSuporte = precoAtual < suporteCritico;

const anomalia = Math.abs(variacao1hEstimada) >= 5.0 || quebrouSuporte;

return [{
  json: {
    preco_btc_usd: precoAtual,
    variacao_1h_pct: parseFloat(variacao1hEstimada.toFixed(2)),
    variacao_24h_pct: variacao24h,
    quebrou_suporte: quebrouSuporte,
    nivel_suporte_usd: suporteCritico,
    anomalia_detectada: anomalia
  }
}];
